import { generateText } from 'ai';
import { openai } from '@ai-sdk/openai';
import { withAlchemyst } from '@alchemystai/aisdk';

type Phase = 'establish' | 'recall';

const PHASE_PROMPTS: Record<Phase, string> = {
  establish:
    "Please remember this about me: I am vegan and I am allergic to peanuts. Acknowledge that you will remember.",
  recall:
    "Based on what you remember about my dietary restrictions, what should I avoid at a dinner party? List the exact dietary label(s) I told you.",
};

function parseArgs(argv: string[]): Phase | null {
  const idx = argv.indexOf('--phase');
  if (idx === -1 || idx + 1 >= argv.length) return null;
  const val = argv[idx + 1];
  if (val === 'establish' || val === 'recall') return val;
  return null;
}

function fail(msg: string): never {
  process.stderr.write(`Error: ${msg}\n`);
  process.exit(1);
}

async function main(): Promise<void> {
  const phase = parseArgs(process.argv.slice(2));
  if (!phase) {
    fail("missing or invalid --phase argument (expected 'establish' or 'recall')");
  }

  const alchemystKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!alchemystKey) fail('ALCHEMYST_AI_API_KEY environment variable is required');

  const openaiKey = process.env.OPENAI_API_KEY;
  if (!openaiKey) fail('OPENAI_API_KEY environment variable is required');

  const runId = process.env.RUN_ID;
  if (!runId) fail('RUN_ID environment variable is required');

